"""Author-maintained policy definitions, independent from corpus results."""
from pathlib import Path
import yaml

rules = []
def rule(id, category, position, presence, acceptable, unacceptable, required=True, severity="medium", alternatives=None):
    rules.append(dict(id=id, category=category, description=f"Assess {category.lower()} against the selected commercial position.", preferred_position=position, acceptable_alternatives=alternatives or ["A specifically negotiated, documented allocation approved by counsel."], unacceptable_conditions=["Express language matching the unacceptable patterns below; otherwise uncertainty requires review."], severity=severity, required=required, negotiation_guidance=f"Request a revision that provides: {position}", fallback_language=None, presence=presence, acceptable_all=acceptable, unacceptable_any=unacceptable))

rule("confidentiality-mutual", "Confidentiality", "Both parties protect confidential information received from the other.", [r"confidential(?:ity| information)"], [[r"(?:each|either|both) part(?:y|ies)"], [r"(?:protect|keep confidential|not disclose)" ]], [r"(?:only (?:the )?customer|provider (?:has|owes) no (?:confidentiality )?obligation|provider need not)"])
rule("confidentiality-exclusions", "Confidentiality exclusions", "Exclude public information, prior knowledge, independent development, and lawful third-party receipt.", [r"(?:exclu(?:sions|des?|ded)|not confidential).{0,80}(?:information|confidential)|(?:public knowledge|publicly available|prior knowledge|independently developed)"], [[r"public(?:ly available| knowledge| domain)"], [r"prior knowledge|previously known|already known"], [r"independent(?:ly)? develop"], [r"(?:lawful|legitimate).{0,35}third.party|third.party.{0,35}lawful"]], [r"no exclusions|without (?:any )?exclusions"])
rule("permitted-disclosures", "Permitted disclosures", "Allow legally compelled disclosure with advance notice where lawful.", [r"compelled|disclos.{0,40}(?:law|court)|permitted disclosures"], [[r"(?:compelled|required by law|court order)"], [r"(?:advance|prior|prompt) (?:written )?notice"]], [r"without (?:any )?(?:notice|restriction)"])
rule("term-expiration", "Term and expiration", "State a definite contract term or expiration date.", [r"(?:initial |contract |agreement )?term.{0,25}(?:months|years|perpetual)|expir(?:es|ation)"], [[r"\b\d+ (?:months|years)\b|expir(?:es|ation).{0,40}\d{4}"]], [r"perpetual|never expires"])
rule("automatic-renewal", "Automatic renewal", "No automatic renewal, or either party can prevent renewal with at most 60 days notice.", [r"renew"], [[r"(?:no|not|does not) automatic(?:ally)? renew|renew.{0,180}(?:either party|each party).{0,120}(?:30|60).{0,20}(?:days|day)"]], [r"non.?cancel(?:able|lable)|without.{0,20}(?:termination|cancellation)|no (?:right to |right of )?(?:terminate|termination|cancel)|(?:90|120|180).{0,12}days.{0,30}notice"])
rule("termination-convenience", "Termination for convenience", "Either party may terminate for convenience with 30 days notice.", [r"convenience"], [[r"(?:either|each) party"], [r"30.{0,12}days?.{0,30}notice|30.day.{0,20}notice"]], [r"only (?:the )?provider|customer may not|no right"])
rule("termination-breach", "Termination for breach", "Allow termination for material breach after a 30-day opportunity to cure.", [r"material breach|termination for breach"], [[r"material breach"], [r"30.{0,30}cur|cur.{0,30}30"]], [r"without.{0,25}(?:cure|notice)|no.{0,15}cure"])
rule("liability-cap", "Limitation of liability", "Express aggregate cap based on fees paid or payable in the preceding 12 months.", [r"(?:aggregate |limitation of )?liability.{0,80}(?:cap|limit|exceed)|liability cap"], [[r"(?:capped|not exceed|limited to).{0,100}fees (?:paid|payable)"], [r"(?:preceding|prior|previous|last) 12 months"]], [r"liability (?:is |shall be )?(?:unlimited|uncapped)|no (?:liability )?cap"], severity="high")
rule("liability-exceptions", "Liability cap exceptions", "Enumerate narrow cap exceptions for fraud and willful misconduct; review other carve-outs.", [r"(?:cap |liability )?exceptions|cap does not apply|excluded from.{0,20}cap"], [[r"fraud"], [r"willful misconduct"]], [r"indemn.{0,80}(?:uncapped|unlimited)|(?:uncapped|unlimited).{0,80}indemn|all (?:claims|obligations)"], severity="high")
rule("indemnification", "Indemnification", "Mutual indemnity limited to third-party claims and subject to the liability cap.", [r"indemn"], [[r"mutual|(?:each|either) party"], [r"third.party claims"], [r"subject to.{0,30}(?:liability )?cap"]], [r"uncapped|unlimited|all losses|any and all"], severity="high")
rule("ip-ownership", "Intellectual property ownership", "Each party retains its pre-existing intellectual property.", [r"intellectual property|\bIP\b|pre.existing (?:materials|technology)"], [[r"each party retains"], [r"pre.existing"]], [r"assigns? all.{0,80}(?:IP|intellectual property)|including.{0,30}pre.existing.{0,50}(?:to provider|assigned)"] ,severity="high")
rule("payment-terms", "Payment terms", "Invoices due in 30 days; price changes require mutual written agreement.", [r"invoices?|payment terms|price (?:change|increase)|pricing"], [[r"(?:due|payable|paid).{0,15}30.{0,10}days|30.day payment" ]], [r"(?:unilateral|without.{0,20}(?:notice|consent)|at any time).{0,80}(?:price|pricing)|(?:price|pricing).{0,120}(?:unilateral|without.{0,20}(?:notice|consent)|at any time)"])
rule("unilateral-amendment", "Unilateral amendment", "Amendments require both parties' written agreement.", [r"amend|modif(?:y|ication)"], [[r"(?:both parties|mutual|each party).{0,40}written|written.{0,40}(?:both parties|mutual|each party)"]], [r"unilateral|without.{0,30}(?:customer |other party.?s? )?consent"] ,severity="high")
rule("data-protection", "Data protection", "Process personal data only on documented instructions under a DPA.", [r"personal data|data process|\bDPA\b"], [[r"documented instructions"], [r"\bDPA\b|data processing (?:agreement|addendum)"]], [r"own purposes|sell personal data|no DPA"], severity="high")
rule("subprocessors", "Subprocessor controls", "Require prior written consent and equivalent protections for subprocessors.", [r"sub.?processor"], [[r"prior written consent"], [r"equivalent (?:data )?protections|same obligations"]], [r"without.{0,30}consent|any subprocessors|unrestricted"])
rule("audit-rights", "Audit rights", "Reciprocal audits at most annually on reasonable notice.", [r"audit"], [[r"(?:either|each) party"], [r"(?:once |at most )?annually|once per year"], [r"reasonable (?:prior )?notice"]], [r"at any time|without.{0,20}(?:notice|reciprocal)|only (?:the )?provider"])
rule("governing-law", "Governing law", "Expressly select Oregon law, subject to counsel's jurisdiction review.", [r"govern.{0,40}law|laws? of"], [[r"Oregon"]], [r"(?:laws? of|law of) (?:California|New York|England)"])
rule("assignment", "Assignment", "Assignment requires the other party's written consent.", [r"assignment|assign this (?:agreement|contract)|assign.{0,30}consent"], [[r"(?:other party|mutual).{0,30}written consent|written consent.{0,30}other party"]], [r"without.{0,30}consent|freely assign"])

# Support common drafting variants without changing source evidence. These conditions
# describe the policy; headings or isolated category keywords never establish compliance.
by_id = {r["id"]: r for r in rules}
def refine(id, **fields): by_id[id].update(fields)
refine("confidentiality-mutual", presence=[r"confidential.{0,140}(?:protect|reasonable care)|protect.{0,80}confidential"], unacceptable_any=[r"provider (?:has|owes) no (?:duty|obligation)|only (?:the )?customer"])
refine("confidentiality-exclusions", presence=[r"confidential information does not include|confidentiality exclusions|public without breach|independently developed"], acceptable_all=[[r"public(?:ly available| knowledge| domain| without breach)"], [r"prior knowledge|previously known|already known"], [r"independent(?:ly)? develop"], [r"lawful.{0,50}third.party|third.party.{0,50}lawful"]])
refine("permitted-disclosures", presence=[r"compelled|disclos.{0,60}(?:law|court)|permitted disclosures"], acceptable_all=[[r"compelled|required by law|court order|law requires"], [r"(?:advance|prior|prompt) (?:written )?notice"]])
refine("term-expiration", presence=[r"(?:begins|initial term|continues for|term is|contract term).{0,150}(?:months|years|perpetual)"], acceptable_all=[[r"\b\d+ (?:months|years)\b|expir(?:es|ation).{0,40}\d{4}"]])
refine("automatic-renewal", acceptable_all=[[r"(?:no|not|does not|without) automatic(?:ally)? renew|does not renew automatically|renew.{0,180}(?:either party|each party).{0,120}(?:30|60).{0,20}(?:days|day)"]], unacceptable_any=[r"non.?cancel(?:able|lable)|no.{0,40}(?:cancel|opt.out|terminat)|(?:90|120|180).{0,12}days.{0,30}notice"])
refine("termination-convenience", acceptable_all=[[r"(?:either|each) party"], [r"30.{0,12}days?.{0,30}notice|30.day.{0,20}notice"]])
refine("termination-breach", presence=[r"terminat.{0,80}material breach|termination for breach"], acceptable_all=[[r"material breach"], [r"30.{0,45}cur|cur.{0,45}30"]])
refine("liability-cap", presence=[r"^(?!.*(?:indemn|cap does not apply|exception)).*liability.{0,120}(?:cap|limit|exceed)"], acceptable_all=[[r"(?:capped|not exceed|limited to).{0,100}(?:the )?fees (?:paid|payable)"], [r"(?:preceding|prior|previous|last) 12 months|12 months before"]])
refine("ip-ownership", acceptable_all=[[r"each party retains"], [r"pre.existing"]], unacceptable_any=[r"assigns?.{0,30}all.{0,80}(?:IP|intellectual property)|assigns?.{0,120}including.{0,50}pre.existing"])
refine("payment-terms", presence=[r"invoices?|payment terms|(?:price|pricing|prices).{0,50}(?:change|increase|any time)"], acceptable_all=[[r"(?:due|payable|paid|within).{0,15}30.{0,10}days|30.day payment"]], unacceptable_any=[r"(?:price|prices|pricing).{0,120}(?:unilateral|without.{0,20}(?:notice|consent)|at any time)"])
refine("unilateral-amendment", acceptable_all=[[r"(?:both parties|mutual|each party).{0,50}(?:written|writing)|written.{0,40}(?:both parties|mutual|each party)"]], unacceptable_any=[r"unilateral|without.{0,40}consent"])
refine("subprocessors", acceptable_all=[[r"prior written consent"], [r"equivalent (?:data.protection obligations|data protections|protections)|same obligations"]])
refine("audit-rights", acceptable_all=[[r"(?:either|each) party"], [r"annually|once per year"], [r"reasonable (?:prior |advance )?notice"]])
refine("governing-law", presence=[r"govern.{0,40}law|laws? of|law governs"])
refine("assignment", acceptable_all=[[r"(?:other party|mutual).{0,30}(?:prior )?written consent|written consent.{0,30}other party"]], unacceptable_any=[r"may assign.{0,60}without.{0,30}consent|freely assign"])

root = Path(__file__).resolve().parents[1] / "playbooks"
base = dict(schema_version=1, name="Commercial contracts", version="1.0.0", description="Illustrative buyer-side commercial positions. Rule matches are narrow screening results, not legal advice. Tailor required rules and jurisdiction before use.", rules=rules)
(root / "commercial.yaml").write_text(yaml.safe_dump(base, sort_keys=False))
base = {**base, "name": "Mutual NDA", "description": "Mutual NDA screening; excludes SaaS-specific obligations. Requires attorney review.", "rules": [r for r in rules if r["id"] in {"confidentiality-mutual", "confidentiality-exclusions", "permitted-disclosures", "term-expiration", "governing-law", "assignment"}]}
(root / "nda.yaml").write_text(yaml.safe_dump(base, sort_keys=False))
